import json, os, subprocess as S, sys
sys.stdout.reconfigure(encoding='utf-8', errors='replace')
cli, inn, out = sys.argv[1], os.path.normpath(sys.argv[2]), os.path.normpath(sys.argv[3])
def unc(p):
    d, rest = os.path.splitdrive(p)
    return '\\\\localhost\\' + d[0] + '$' + rest
uo, ui = unc(out), unc(inn)
if not (os.path.isdir(uo) and os.path.isdir(ui)):
    print('VERDICT bad: UNC admin share not reachable here: ' + uo); sys.exit(1)
def sub(o):
    if isinstance(o, str):
        return o.replace('@UNC_OUT@', uo).replace('@UNC_IN@', ui).replace('@OUT@', out)
    if isinstance(o, list):
        return [sub(v) for v in o]
    if isinstance(o, dict):
        return {k: sub(v) for k, v in o.items()}
    return o
calls = sub(json.loads(sys.argv[4]))
p = S.Popen([cli, 'mcp', '--headless', '--automation-read-root', inn, '--automation-read-root', out,
             '--automation-write-root', out], stdin=S.PIPE, stdout=S.PIPE, stderr=S.PIPE, cwd=out)
def w(m):
    p.stdin.write((json.dumps(m) + '\n').encode()); p.stdin.flush()
def r(i):
    for line in p.stdout:
        m = json.loads(line)
        if m.get('id') == i:
            return m
    print('VERDICT bad: server closed stdout'); sys.exit(1)
w({'jsonrpc': '2.0', 'id': 1, 'method': 'initialize', 'params': {'protocolVersion': '2025-06-18', 'capabilities': {}, 'clientInfo': {'name': 'unc-probe', 'version': '1'}}})
r(1)
w({'jsonrpc': '2.0', 'method': 'notifications/initialized'})
lines, bad = [], 0
for n, c in enumerate(calls):
    t, g, want = c[0], c[1], c[2]
    w({'jsonrpc': '2.0', 'id': n + 2, 'method': 'tools/call', 'params': {'name': t, 'arguments': g}})
    m = r(n + 2); res = m.get('result') or {}
    err = bool(res.get('isError') or 'error' in m)
    txt = (' '.join(x.get('text', '') for x in res.get('content', [])) or json.dumps(m.get('error'))).replace('\n', ' ')
    ok = (not err) if want == 'OK' else (err and want.startswith('ERROR:') and want[6:] in txt)
    if len(c) > 3 and os.path.exists(c[3]):
        ok = False; txt += ' [WRITTEN: ' + c[3] + ']'
    bad += not ok
    lines.append(('match ' if ok else 'MISMATCH ') + ('ERROR ' if err else 'OK ') + t + ' ' + json.dumps(g)[:160] + ': ' + txt[:300])
p.stdin.close(); p.wait(15)
print('VERDICT ok' if not bad else 'VERDICT bad: %d of %d calls did not match' % (bad, len(calls)))
print('\n'.join(lines))
sys.exit(1 if bad else 0)
